<template>
  <main class="app-shell page-shell practice-page"><LearnerHeader /><header class="section-header"><button class="back-button" @click="router.back()">‹</button><div><h1>{{ task?.title||'广播词考试' }}</h1><p>正式考核 · 限次录音 · 整卷提交</p></div></header><PageState v-if="loading" tone="loading" title="正在加载考试"/><PageState v-else-if="!task" tone="error" title="考试无法读取" :message="errorMessage" action-label="重试" @action="loadExam"/><AssignmentLearningCards v-if="task && assignmentId" :assignment-id="assignmentId" /><section v-if="task" class="practice-card"><span class="task-pill exam-pill">考试任务</span><h2>整卷录音</h2><p>考试录音与练习记录严格分离，整卷提交后进入 AI + 人工测评。</p><div class="exam-rule"><span>最大录音次数</span><strong>{{ task?.max_recordings||1 }}</strong></div><div class="record-panel"><button class="record-button" :disabled="submitting || !task" :class="{recording}" @click="recording?stopRecording():startRecording()">{{ recording?'停止录音':audioBlob?'重新录音':'开始考试录音' }}</button><span>{{ recording?'正在录制整卷…':audioBlob?`录音完成 ${formatDuration(durationMs)}`:'请完成整卷录音' }}</span></div><audio v-if="audioPreview" controls :src="audioPreview"/><button class="primary-button" :disabled="submitting||recording||!audioBlob" @click="submit">{{ submitting?'上传并提交中…':'提交整卷考试' }}</button></section><section v-if="submitted" class="feedback-card"><div class="feedback-heading"><div><span>考试已提交</span><strong>等待测评</strong></div><small>录音 {{ submitted.recording_count }} / {{ submitted.max_recordings }}</small></div><p>测评员完成 AI 证据复核并发布成绩后，可在学习记录中查看。</p><button class="outline-button" @click="router.push('/student/record')">查看学习记录 →</button></section><p v-if="errorMessage" class="form-error">{{ errorMessage }}</p><BottomNav /></main>
</template>
<script setup lang="ts">
import PageState from '@/components/PageState.vue'; import { learnerError } from '@/domain/learnerPresentation'
import BottomNav from '@/components/BottomNav.vue'
import LearnerHeader from '@/components/LearnerHeader.vue'
import AssignmentLearningCards from "@/components/AssignmentLearningCards.vue"
import { onBeforeUnmount,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { cabinlingoApi } from '@/api'
const route=useRoute();const router=useRouter();const assignmentId=String(route.query.assignment||'');const taskId=String(route.query.task||'');const loading=ref(true);const task=ref<{title:string;max_recordings:number}|null>(null);const recording=ref(false);const audioBlob=ref<Blob|null>(null);const audioPreview=ref('');const durationMs=ref(0);const submitting=ref(false);const errorMessage=ref('');const submitted=ref<{recording_count:number;max_recordings:number}|null>(null);let recorder:MediaRecorder|null=null;let stream:MediaStream|null=null;let chunks:BlobPart[]=[];let startedAt=0
async function startRecording(){if(submitting.value)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){errorMessage.value='当前浏览器不支持录音';return}try{stream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=finish;recorder.start(500);startedAt=Date.now();recording.value=true}catch{errorMessage.value='无法访问麦克风，请检查浏览器权限'}}function stopRecording(){recorder?.stop()}function finish(){recording.value=false;durationMs.value=Date.now()-startedAt;audioBlob.value=new Blob(chunks,{type:recorder?.mimeType||'audio/webm'});if(audioPreview.value)URL.revokeObjectURL(audioPreview.value);audioPreview.value=URL.createObjectURL(audioBlob.value);stream?.getTracks().forEach(t=>t.stop())}
async function submit(){if(submitting.value||recording.value||!audioBlob.value)return;submitting.value=true;errorMessage.value='';try{const audio=await cabinlingoApi.uploadAudio({assignment_id:assignmentId,purpose:'exam',blob:audioBlob.value,duration_ms:durationMs.value});submitted.value=await cabinlingoApi.submitExam(taskId,{assignment_id:assignmentId,recording_refs:[audio.audio_ref],paper_item_ids:['whole-paper']})}catch{errorMessage.value='提交失败，可能已达到次数限制或考试已提交'}finally{submitting.value=false}}function formatDuration(ms:number){const s=Math.round(ms/1000);return `${Math.floor(s/60)}分${s%60}秒`}
async function loadExam(){loading.value=true;errorMessage.value='';if(!assignmentId||!taskId){errorMessage.value='缺少考试参数';loading.value=false;return}try{task.value=await cabinlingoApi.examTask(taskId)}catch(error){errorMessage.value=learnerError(error)}finally{loading.value=false}};onMounted(loadExam);onBeforeUnmount(()=>{stream?.getTracks().forEach(t=>t.stop());if(audioPreview.value)URL.revokeObjectURL(audioPreview.value)})
</script>
<style scoped>.practice-page{max-width:680px}.practice-card,.feedback-card{padding:24px;border-radius:22px;background:#fff;box-shadow:0 8px 24px #2447810c}.practice-card h2{margin:18px 0 8px}.practice-card p{color:#8998b2}.exam-pill{color:#249b73;background:#eafaf3}.exam-rule{display:flex;justify-content:space-between;padding:16px;margin:18px 0;border-radius:12px;background:#f3f7fd;color:#7182a0}.exam-rule strong{color:#249b73;font-size:22px}.record-panel{display:flex;align-items:center;gap:14px;padding:16px;margin:18px 0;border-radius:14px;background:#f3f7fd;color:#7e8eaa}.record-button{padding:12px 17px;border-radius:10px;color:#fff;background:#24a97a}.record-button.recording{background:#e45c70}.practice-card audio{width:100%;margin-bottom:15px}.feedback-card{margin-top:18px}.feedback-heading{display:flex;justify-content:space-between}.feedback-heading span,.feedback-heading strong{display:block}.feedback-heading strong{margin-top:7px;color:#249b73;font-size:23px}.feedback-card p{color:#61718f;line-height:1.7}</style>
